81	// LoadAdapter loads the loras in inference engines
82	func (c *loraClient) LoadAdapter(ctx context.Context, instance *modelv1alpha1.ModelAdapter, targetPod *corev1.Pod) (loaded bool, exists bool, err error) {
83		// Determine whether to use runtime sidecar:
84		// - If global flag is disabled, always use direct engine API
