89		} else {
90			klog.V(4).InfoS("Using direct engine API for adapter loading", "pod", targetPod.Name, "adapter", instance.Name)
91		}
92	
93		urls := BuildURLs(targetPod.Status.PodIP, c.runtimeConfig, useSidecar, metrics.GetEngineType(*targetPod))
94	
95		models, err := c.getModels(urls.ListModelsURL, instance)
96		if err != nil {
97			return false, false, err
98		}
99		if models[instance.Name] {
100			return false, true, nil
101		}
102	
