111	func (c *loraClient) UnloadAdapter(instance *modelv1alpha1.ModelAdapter, targetPod *corev1.Pod) error {
112		// Determine whether to use runtime sidecar:
113		// - If global flag is disabled, always use direct engine API
114		// - If global flag is enabled, detect if pod has sidecar container
115		useSidecar := c.runtimeConfig.EnableRuntimeSidecar && DetectRuntimeSidecar(targetPod)
116		if useSidecar {
117			klog.V(4).InfoS("Using runtime sidecar API for adapter unload", "pod", targetPod.Name, "adapter", instance.Name)
118		} else {
119			klog.V(4).InfoS("Using direct engine API for adapter unload", "pod", targetPod.Name, "adapter", instance.Name)
120		}
121	
122		// Build payload using helper function
123		payloadBytes, err := buildUnloadPayload(instance, useSidecar)
124		if err != nil {
125			return err
126		}
127	
128		urls := BuildURLs(targetPod.Status.PodIP, c.runtimeConfig, useSidecar, metrics.GetEngineType(*targetPod))
129		req, err := http.NewRequest("POST", urls.UnloadAdapterURL, bytes.NewBuffer(payloadBytes))
130		if err != nil {
131			return err
132		}
133		req.Header.Set("Content-Type", "application/json")
134		if token, ok := instance.Spec.AdditionalConfig["api-key"]; ok {
135			req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", token))
136		}
137	
138		resp, err := c.httpClient.Do(req)
139		if err != nil {
140			klog.ErrorS(err, "Failed to call unload lora adapter api", "url", urls.UnloadAdapterURL)
141			return nil // ignore http errors
142		}
143	
144		defer func() {
145			if err := resp.Body.Close(); err != nil {
146				klog.InfoS("Error closing response body:", err)
147			}
148		}()
149	
150		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
151			body, err := io.ReadAll(io.LimitReader(resp.Body, 4096))
