207	// Separate method to load the LoRA adapter
208	func (c *loraClient) loadAdapterCall(ctx context.Context, url string, instance *modelv1alpha1.ModelAdapter, useSidecar bool) error {
209		var payloadBytes []byte
210		var err error
211	
212		// Build payload based on runtime mode
213		if useSidecar {
214			// Runtime path - send original URL for artifact delegation
215			payload := map[string]interface{}{
216				"lora_name":    instance.Name,
217				"artifact_url": instance.Spec.ArtifactURL, // Send original URL unchanged
218			}
219	
220			// Add credentials if provided
221			if instance.Spec.CredentialsSecretRef != nil && c.k8sClient != nil {
222				secret, err := c.k8sClient.CoreV1().Secrets(instance.Namespace).Get(ctx, instance.Spec.CredentialsSecretRef.Name, metav1.GetOptions{})
223				if err != nil {
224					klog.ErrorS(err, "Failed to get credentials secret", "secret", instance.Spec.CredentialsSecretRef.Name, "namespace", instance.Namespace)
225					return err
226				}
227	
228				// Convert secret data to string map
229				credentials := make(map[string]string)
230				for k, v := range secret.Data {
231					credentials[k] = string(v)
232				}
233				payload["credentials"] = credentials
234			}
235	
236			// Add additional config if provided
237			if instance.Spec.AdditionalConfig != nil {
238				payload["additional_config"] = instance.Spec.AdditionalConfig
239			}
240	
241			payloadBytes, err = sonic.Marshal(payload)
242			if err != nil {
243				return err
244			}
245	
246			klog.V(4).InfoS("Using runtime path for artifact delegation",
247				"ModelAdapter", klog.KObj(instance),
248				"artifactURL", instance.Spec.ArtifactURL)
249	
250		} else {
251			// Direct path - transform URL for engine (existing logic)
252			artifactURL := instance.Spec.ArtifactURL
253	
254			// Transform huggingface:// URLs to paths
255			if strings.HasPrefix(instance.Spec.ArtifactURL, "huggingface://") {
256				var err error
257				artifactURL, err = extractHuggingFacePath(instance.Spec.ArtifactURL)
258				if err != nil {
259					klog.ErrorS(err, "Invalid artifact URL", "artifactURL", artifactURL)
260					return err
261				}
262			}
263			// TODO: Add support for other URL transformations if needed
264	
265			payload := map[string]string{
266				"lora_name": instance.Name,
267				"lora_path": artifactURL,
268			}
269	
270			payloadBytes, err = sonic.Marshal(payload)
271			if err != nil {
272				return err
273			}
274	
275			klog.V(4).InfoS("Using direct path to engine",
276				"ModelAdapter", klog.KObj(instance),
277				"transformedURL", artifactURL)
278		}
279	
280		// Send HTTP request
281		req, err := http.NewRequestWithContext(ctx, "POST", url, bytes.NewBuffer(payloadBytes))
282		if err != nil {
283			return err
284		}
285		req.Header.Set("Content-Type", "application/json")
286	
287		// Check if "api-key" exists in the map and set the Authorization header accordingly
288		if token, ok := instance.Spec.AdditionalConfig["api-key"]; ok {
289			req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", token))
290		}
291	
292		resp, err := c.httpClient.Do(req)
293		if err != nil {
294			return err
295		}
296		defer func() {
297			if err := resp.Body.Close(); err != nil {
298				klog.InfoS("Error closing response body:", err)
299			}
300		}()
301	
302		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
303			body, err := io.ReadAll(io.LimitReader(resp.Body, 4096))
304			if err != nil {
305				return fmt.Errorf("failed to load LoRA adapter (status %d), and failed to read response body: %w", resp.StatusCode, err)
306			}
307			return fmt.Errorf("failed to load LoRA adapter (status %d): %s", resp.StatusCode, body)
308		}
309	
310		klog.InfoS("Successfully loaded LoRA adapter",
311			"ModelAdapter", klog.KObj(instance),
312			"url", url)
313	
314		return nil
315	}
316	
317	// buildUnloadPayload creates the unload request payload based on runtime mode
318	func buildUnloadPayload(instance *modelv1alpha1.ModelAdapter, useSidecar bool) ([]byte, error) {
319		var payloadBytes []byte
320		var err error
321	
322		if useSidecar {
323			// Runtime path - include cleanup flag
324			payload := map[string]interface{}{
325				"lora_name":     instance.Name,
326				"cleanup_local": true, // Clean up local artifacts on unload
327			}
328			payloadBytes, err = sonic.Marshal(payload)
329		} else {
330			// Direct path - simple unload
331			payload := map[string]string{
332				"lora_name": instance.Name,
333			}
334			payloadBytes, err = sonic.Marshal(payload)
335		}
336	
337		return payloadBytes, err
338	}
